/// Windows GeoId for an alpha-2 country code.
pub fn geoid_for(alpha2: &str) -> Option<&'static str> {
    COUNTRY_GEOID
        .binary_search_by(|(code, _)| (*code).cmp(alpha2))
        .ok()
        .map(|i| COUNTRY_GEOID[i].1)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_is_sorted() {
        let mut sorted = COUNTRY_GEOID.to_vec();
        sorted.sort_unstable();
        assert_eq!(sorted, COUNTRY_GEOID.to_vec());
    }

    #[test]
    fn known_codes() {
        // Windows GeoIds, not ISO numerics.
        assert_eq!(geoid_for("RU"), Some("203"));
        assert_eq!(geoid_for("FR"), Some("84"));
        assert_eq!(geoid_for("US"), Some("244"));
        assert_eq!(geoid_for("DE"), Some("94"));
        assert_eq!(geoid_for("XX"), None);
        assert_eq!(geoid_for("fr"), None, "alpha-2 must be uppercase");
    }
}
